"use client";

import { useLayoutEffect, useRef, useState } from "react";
import {
  ArrowLeft,
  Hash,
  List,
  MessageSquare,
  UserRound,
  X,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { ChannelList, studioChannels, type ChatChannel } from "./channel-list";
import { ChatComposer } from "./chat-composer";
import {
  MessageReactions,
  studioReactions,
  toggleReaction,
  type ChatReaction,
} from "./message-reactions";
import {
  ChatPostBody,
  MessageThread,
  ownPost,
  studioPost,
  studioReply,
  type ChatPost,
} from "./message-thread";

export type ConversationPost = ChatPost & {
  reactions?: ChatReaction[];
  replies?: ChatPost[];
};
const starter: Record<string, ConversationPost[]> = {
  studio: [
    {
      id: "welcome",
      author: "Лев Ким",
      initials: "LK",
      time: "09:32",
      text: "Добавил два варианта перехода в прототип урока. Можно забирать на ревью.",
      resource: {
        title: "Практика в редакторе",
        detail: "Code Exercise · Takt",
        href: "https://takt-ui.vercel.app/ru/components/code-exercise",
      },
    },
    { ...studioPost, reactions: studioReactions, replies: [studioReply] },
  ],
  code: [
    {
      id: "code-review",
      author: "Лев Ким",
      initials: "LK",
      time: "10:12",
      text: "Можно ли сохранить фокус в редакторе после запуска тестов?",
    },
  ],
  maya: [
    {
      id: "hello",
      author: "Майя Ли",
      initials: "ML",
      time: "10:24",
      text: "Привет! Сюда можно присылать вопросы один на один.",
    },
  ],
};
const emptyReactions = studioReactions.map((item) => ({ ...item, count: 0 }));

export function CourseMessenger({
  channels = studioChannels,
  initialMessages = starter,
  messages: controlledMessages,
  onSend,
  onToggleReaction,
  workspace = "Design Lab",
  className = "h-[31rem]",
}: {
  messages?: Record<string, ConversationPost[]>;
  onSend?: (
    channelId: string,
    text: string,
    parentId?: string,
  ) => void | Promise<void>;
  onToggleReaction?: (channelId: string, postId: string, emoji: string) => void;
  channels?: ChatChannel[];
  initialMessages?: Record<string, ConversationPost[]>;
  workspace?: string;
  className?: string;
}) {
  const [channelId, select] = useState(channels[0]?.id);
  const [localMessages, setMessages] = useState(initialMessages);
  const messages = controlledMessages ?? localMessages;
  const [pending, setPending] = useState<Record<string, boolean>>({});
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [threadId, setThreadId] = useState<string | null>(null);
  const [showNav, setShowNav] = useState(false);
  const stream = useRef<HTMLDivElement>(null);
  const threadTrigger = useRef<HTMLButtonElement | null>(null);
  const closeButton = useRef<HTMLButtonElement>(null);
  const navTrigger = useRef<HTMLButtonElement>(null);
  const backButton = useRef<HTMLButtonElement>(null);
  const channel = channels.find((item) => item.id === channelId) ?? channels[0];
  const id = channel?.id ?? "";
  const posts = messages[id] ?? [];
  const thread = posts.find((item) => item.id === threadId);
  const lastPost = posts.at(-1)?.id;
  useLayoutEffect(() => {
    const node = stream.current;
    if (node) node.scrollTop = node.scrollHeight;
  }, [id, lastPost]);
  useLayoutEffect(() => {
    if (threadId) closeButton.current?.focus({ preventScroll: true });
  }, [threadId]);
  useLayoutEffect(() => {
    if (showNav) backButton.current?.focus({ preventScroll: true });
  }, [showNav]);

  function updatePost(
    postId: string,
    change: (post: ConversationPost) => ConversationPost,
  ) {
    setMessages((previous) => ({
      ...previous,
      [id]: (previous[id] ?? []).map((post) =>
        post.id === postId ? change(post) : post,
      ),
    }));
  }
  async function send(text: string, parentId?: string) {
    if (onSend) {
      const key = JSON.stringify(
        parentId === undefined ? [id] : [id, parentId],
      );
      setPending((previous) => ({ ...previous, [key]: true }));
      try {
        await onSend(id, text, parentId);
      } finally {
        setPending((previous) => ({ ...previous, [key]: false }));
      }
    }
    if (controlledMessages !== undefined) return;
    const message = ownPost(text);
    if (parentId)
      updatePost(parentId, (post) => ({
        ...post,
        replies: [...(post.replies ?? []), message],
      }));
    else
      setMessages((previous) => ({
        ...previous,
        [id]: [...(previous[id] ?? []), message],
      }));
  }
  function react(postId: string, emoji: string) {
    onToggleReaction?.(id, postId, emoji);
    if (controlledMessages === undefined)
      updatePost(postId, (post) => ({
        ...post,
        reactions: toggleReaction(post.reactions ?? emptyReactions, emoji),
      }));
  }
  function remember(key: string, text: string) {
    setDrafts((previous) => ({ ...previous, [key]: text }));
  }
  function closeThread() {
    setThreadId(null);
    requestAnimationFrame(() =>
      threadTrigger.current?.focus({ preventScroll: true }),
    );
  }
  function hideNav() {
    setShowNav(false);
    requestAnimationFrame(() =>
      navTrigger.current?.focus({ preventScroll: true }),
    );
  }
  if (!channel)
    return <p className="p-4 text-sm text-muted-foreground">Нет диалогов</p>;
  const channelDraft = JSON.stringify([id]);
  const threadDraft = JSON.stringify([id, threadId]);
  const Icon = channel.kind === "direct" ? UserRound : Hash;
  return (
    <section
      aria-label="Мессенджер курса"
      className={"@container w-full min-w-0 text-foreground " + className}
    >
      <div className="flex h-full overflow-hidden rounded-2xl border bg-card shadow-sm">
        <aside
          className={
            (showNav ? "flex" : "hidden") +
            " w-full flex-col overflow-y-auto bg-sidebar p-2 @min-[650px]:flex @min-[650px]:w-48 @min-[650px]:shrink-0 @min-[650px]:border-r"
          }
        >
          <Button
            ref={backButton}
            variant="ghost"
            className="mb-1 self-start @min-[650px]:hidden"
            onClick={hideNav}
          >
            <ArrowLeft />К переписке
          </Button>
          <div className="[&>nav]:max-w-none [&>nav]:border-0 [&>nav]:p-1.5">
            <ChannelList
              channels={channels}
              value={id}
              workspace={workspace}
              onSelect={(next) => {
                select(next);
                setThreadId(null);
                if (showNav) hideNav();
              }}
            />
          </div>
        </aside>
        <div
          className={
            (thread
              ? "hidden @min-[900px]:flex "
              : showNav
                ? "hidden @min-[650px]:flex "
                : "flex ") + "min-w-0 flex-1 flex-col"
          }
        >
          <header className="flex min-h-15 items-center gap-2 border-b px-3 @min-[650px]:px-5">
            <Button
              ref={navTrigger}
              variant="outline"
              size="icon"
              aria-label="Выбрать диалог"
              className="@min-[650px]:hidden"
              onClick={() => setShowNav(true)}
            >
              <List />
            </Button>
            <Icon size={18} className="shrink-0 text-muted-foreground" />
            <div className="min-w-0">
              <h2 className="truncate text-sm font-semibold">{channel.name}</h2>
              <p className="truncate text-xs text-muted-foreground">
                {channel.topic}
              </p>
            </div>
          </header>
          <div
            ref={stream}
            className="min-h-0 flex-1 space-y-5 overflow-y-auto overscroll-contain p-4 @min-[650px]:p-5"
          >
            {posts.length === 0 && (
              <p className="text-sm text-muted-foreground">
                Начните обсуждение
              </p>
            )}
            {posts.map((post) => (
              <ChatPostBody key={post.id} post={post}>
                <div className="mt-2 flex flex-wrap items-center gap-2">
                  <MessageReactions
                    reactions={post.reactions ?? emptyReactions}
                    onToggle={(emoji) => react(post.id, emoji)}
                  />
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-xs text-muted-foreground"
                    onClick={(event) => {
                      threadTrigger.current = event.currentTarget;
                      setThreadId(post.id);
                    }}
                  >
                    <MessageSquare />
                    {post.replies?.length ? (
                      <>Ответы · {post.replies.length}</>
                    ) : (
                      "Ответить"
                    )}
                  </Button>
                </div>
              </ChatPostBody>
            ))}
          </div>
          <div className="p-2.5 pt-0 @min-[650px]:p-4 @min-[650px]:pt-0">
            <ChatComposer
              pending={pending[channelDraft]}
              key={id}
              value={drafts[channelDraft] ?? ""}
              placeholder={"Сообщение в " + channel.name}
              onChange={(text) => remember(channelDraft, text)}
              onSend={(text) => send(text)}
            />
          </div>
        </div>
        {thread && (
          <aside
            key={thread.id}
            onKeyDown={(event) => {
              if (event.key === "Escape") closeThread();
            }}
            className="relative min-h-0 min-w-0 flex-1 motion-safe:animate-in motion-safe:fade-in motion-safe:slide-in-from-right-2 motion-safe:duration-200 @min-[900px]:max-w-80 @min-[900px]:border-l [&>section]:rounded-none [&>section]:border-0"
          >
            <Button
              ref={closeButton}
              size="icon-sm"
              variant="ghost"
              aria-label="Закрыть тред"
              onClick={closeThread}
              className="absolute top-2 right-2 z-1"
            >
              <X />
            </Button>
            <MessageThread
              pending={pending[threadDraft]}
              parent={thread}
              replies={thread.replies ?? []}
              draft={drafts[threadDraft] ?? ""}
              onDraftChange={(text) => remember(threadDraft, text)}
              onReply={(text) => send(text, thread.id)}
            />
          </aside>
        )}
      </div>
    </section>
  );
}

"use client";

import { cn } from "@/lib/utils";

import { Hash, Layers2, UserRound } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

export type ChatChannel = {
  id: string;
  name: string;
  kind: "channel" | "direct";
  topic: string;
};

export const studioChannels: ChatChannel[] = [
  {
    id: "studio",
    name: "дизайн-студия",
    kind: "channel",
    topic: "Разборы интерфейсов и прототипы курса",
  },
  {
    id: "code",
    name: "ревью-кода",
    kind: "channel",
    topic: "Вопросы по реализации и обратная связь",
  },
  { id: "maya", name: "Майя Ли", kind: "direct", topic: "Наставник курса" },
];

export function ChannelList({
  channels = studioChannels,
  value,
  onSelect,
  workspace = "Design Lab",
  className,
}: {
  className?: string;
  channels?: ChatChannel[];
  value?: string;
  onSelect?: (id: string) => void;
  workspace?: string;
}) {
  const [local, setLocal] = useState(channels[0]?.id);
  const indicator = useId();
  const reduce = useReducedMotion();
  return (
    <nav
      aria-label="Диалоги курса"
      className={cn(
        "w-full max-w-64 rounded-2xl border bg-sidebar p-3 text-left text-sidebar-foreground",
        className,
      )}
    >
      <div className="mb-4 flex items-center gap-2.5 border-b px-1 pb-3">
        <span className="grid size-9 place-items-center rounded-xl bg-primary text-primary-foreground">
          <Layers2 size={18} />
        </span>
        <div>
          <strong className="block text-sm tracking-tight">{workspace}</strong>
          <span className="block text-[11px] leading-tight text-muted-foreground">
            Пространство курса
          </span>
        </div>
      </div>
      {(["channel", "direct"] as const).map((kind) => {
        const group = channels.filter((channel) => channel.kind === kind);
        if (!group.length) return null;
        return (
          <div key={kind} className="mb-3 last:mb-0">
            <p className="mb-1 px-2 text-[11px] font-semibold text-muted-foreground">
              {kind === "channel" ? "Каналы" : "Личные сообщения"}
            </p>
            {group.map((channel) => {
              const active = (value ?? local) === channel.id;
              const Icon = kind === "channel" ? Hash : UserRound;
              return (
                <button
                  type="button"
                  key={channel.id}
                  aria-current={active ? "true" : undefined}
                  onClick={() => {
                    setLocal(channel.id);
                    onSelect?.(channel.id);
                  }}
                  className="relative isolate flex min-h-9 w-full cursor-pointer items-center gap-2 rounded-lg px-2 text-left text-sm outline-offset-1 hover:bg-muted"
                >
                  {active && (
                    <motion.span
                      layoutId={indicator}
                      transition={
                        reduce
                          ? { duration: 0 }
                          : { type: "spring", stiffness: 420, damping: 37 }
                      }
                      className="absolute inset-0 -z-10 rounded-lg border border-primary/15 bg-primary/10"
                    />
                  )}
                  <Icon size={14} aria-hidden className="shrink-0" />
                  <span className="truncate">{channel.name}</span>
                </button>
              );
            })}
          </div>
        );
      })}
    </nav>
  );
}

"use client";

import { cn } from "@/lib/utils";

import { ArrowUp, Check } from "lucide-react";
import { useRef, useState } from "react";
import { Button } from "@/components/ui/button";

export function ChatComposer({
  value,
  onChange,
  onSend,
  placeholder = "Написать сообщение",
  pending = false,
  className,
}: {
  className?: string;
  pending?: boolean;
  value?: string;
  onChange?: (text: string) => void;
  onSend?: (text: string) => void | Promise<void>;
  placeholder?: string;
}) {
  const [draft, setDraft] = useState("");
  const [status, setStatus] = useState<"idle" | "sending" | "sent" | "error">(
    "idle",
  );
  const sending = useRef(false);
  const input = useRef<HTMLTextAreaElement>(null);
  const text = value ?? draft;
  const busy = pending || status === "sending";
  function update(next: string) {
    if (value === undefined) setDraft(next);
    onChange?.(next);
  }
  async function submit() {
    if (!text.trim() || busy || sending.current) return;
    sending.current = true;
    setStatus("sending");
    try {
      await onSend?.(text.trim());
      update("");
      setStatus("sent");
    } catch {
      setStatus("error");
    } finally {
      sending.current = false;
    }
  }
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        void submit();
      }}
      className={cn(
        "w-full min-w-0 rounded-xl border bg-background p-2.5 text-left shadow-xs has-[textarea:focus-visible]:border-ring has-[textarea:focus-visible]:ring-2 has-[textarea:focus-visible]:ring-ring/55 forced-colors:has-[textarea:focus-visible]:outline-2",
        className,
      )}
    >
      <textarea
        ref={input}
        rows={2}
        aria-label={placeholder}
        placeholder={placeholder}
        value={text}
        readOnly={busy}
        onChange={(event) => {
          update(event.target.value);
          setStatus("idle");
        }}
        onKeyDown={(event) => {
          if (
            event.key === "Enter" &&
            !event.shiftKey &&
            !event.nativeEvent.isComposing &&
            event.nativeEvent.keyCode !== 229
          ) {
            event.preventDefault();
            if (!event.repeat) void submit();
          }
        }}
        className="block w-full resize-none bg-transparent px-1 py-0.5 text-sm text-foreground outline-none focus-visible:outline-none! placeholder:text-muted-foreground"
      />
      <div className="flex items-end justify-between gap-2">
        <span
          role="status"
          className="flex items-center gap-1 px-1 text-[11px] text-muted-foreground"
        >
          {status === "sent" ? (
            <>
              <Check size={13} />
              Отправлено
            </>
          ) : status === "error" ? (
            "Ошибка отправки. Попробуйте ещё раз."
          ) : busy ? (
            "Отправка…"
          ) : (
            "Shift + Enter · новая строка"
          )}
        </span>
        <Button
          type="submit"
          size="icon"
          aria-label="Отправить сообщение"
          disabled={!text.trim() || busy}
          className="rounded-full motion-safe:active:scale-90"
          onClick={() => input.current?.focus({ preventScroll: true })}
        >
          <ArrowUp />
        </Button>
      </div>
    </form>
  );
}

"use client";

import { cn } from "@/lib/utils";

import { useState } from "react";
import { SmilePlus } from "lucide-react";
import { Popover } from "radix-ui";
import { motion, useReducedMotion } from "motion/react";

export type ChatReaction = {
  emoji: string;
  label: string;
  count: number;
  mine: boolean;
};
export const studioReactions: ChatReaction[] = [
  { emoji: "👏", label: "Аплодисменты", count: 3, mine: false },
  { emoji: "❤️", label: "Нравится", count: 0, mine: false },
  { emoji: "💡", label: "Хорошая идея", count: 1, mine: false },
];

export function toggleReaction(list: ChatReaction[], emoji: string) {
  return list.map((item) =>
    item.emoji === emoji
      ? {
          ...item,
          mine: !item.mine,
          count: Math.max(0, item.count + (item.mine ? -1 : 1)),
        }
      : item,
  );
}

export function MessageReactions({
  reactions,
  onToggle,
  className,
}: {
  className?: string;
  reactions?: ChatReaction[];
  onToggle?: (emoji: string) => void;
}) {
  const [local, setLocal] = useState(studioReactions);
  const reduce = useReducedMotion();
  const [open, setOpen] = useState(false);
  const items = reactions ?? local;
  function toggle(emoji: string) {
    if (reactions === undefined)
      setLocal((previous) => toggleReaction(previous, emoji));
    onToggle?.(emoji);
  }
  return (
    <div
      className={cn("flex flex-wrap gap-1.5", className)}
      role="group"
      aria-label="Реакции"
    >
      {items
        .filter((item) => item.count > 0)
        .map((item) => (
          <button
            type="button"
            key={item.emoji}
            aria-label={item.label + ", " + item.count}
            aria-pressed={item.mine}
            onClick={() => toggle(item.emoji)}
            className="inline-flex min-h-7 cursor-pointer items-center gap-1.5 rounded-full border bg-card px-2 text-xs font-medium text-muted-foreground tabular-nums transition-colors hover:border-primary/40 aria-pressed:border-primary/40 aria-pressed:bg-primary/10 aria-pressed:text-primary"
          >
            <motion.span
              aria-hidden
              key={String(item.mine)}
              initial={
                item.mine && !reduce ? { scale: 0.75, rotate: -12 } : false
              }
              animate={{ scale: 1, rotate: 0 }}
              transition={{ type: "spring", stiffness: 420, damping: 15 }}
            >
              {item.emoji}
            </motion.span>
            {item.count}
          </button>
        ))}
      {items.some((item) => !item.count) && (
        <Popover.Root open={open} onOpenChange={setOpen}>
          <Popover.Trigger asChild>
            <button
              type="button"
              aria-label="Добавить реакцию"
              className="grid size-7 place-items-center rounded-full border border-dashed text-muted-foreground hover:text-primary"
            >
              <SmilePlus size={14} />
            </button>
          </Popover.Trigger>
          <Popover.Portal>
            <Popover.Content
              side="top"
              sideOffset={5}
              collisionPadding={8}
              aria-label="Реакции"
              className="z-50 flex gap-1 rounded-xl border bg-popover p-1 text-popover-foreground shadow-md"
            >
              {items
                .filter((item) => !item.count)
                .map((item) => (
                  <button
                    type="button"
                    key={item.emoji}
                    aria-label={item.label}
                    className="grid size-8 place-items-center rounded-lg hover:bg-accent"
                    onClick={() => {
                      setOpen(false);
                      toggle(item.emoji);
                    }}
                  >
                    {item.emoji}
                  </button>
                ))}
            </Popover.Content>
          </Popover.Portal>
        </Popover.Root>
      )}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";

import { useLayoutEffect, useRef, useState } from "react";
import { CornerDownRight, MessagesSquare } from "lucide-react";
import { ChatComposer } from "./chat-composer";
import { ChatPostBody, type ChatPost } from "./chat-post";

// Preserve the original thread entry point for installed consumers.
export { ChatPostBody, type ChatPost } from "./chat-post";

export const studioPost: ChatPost = {
  id: "review",
  author: "Майя Ли",
  initials: "ML",
  time: "09:41",
  text: "На ревью сегодня смотрим переход между состояниями. Какую пружину оставим для панели?",
  code: "spring({ stiffness: 320, damping: 30 })",
};
export const studioReply: ChatPost = {
  id: "first-reply",
  author: "Лев Ким",
  initials: "LK",
  time: "09:46",
  text: "Этот вариант хорошо читается даже при быстром переключении.",
};

export function ownPost(text: string): ChatPost {
  return {
    id: crypto.randomUUID?.() ?? Math.random().toString(36).slice(2),
    author: "Вы",
    initials: "Y",
    time: new Date().toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    }),
    text,
  };
}

export function MessageThread({
  parent = studioPost,
  replies,
  draft,
  onDraftChange,
  onReply,
  pending,
  className,
}: {
  className?: string;
  pending?: boolean;
  parent?: ChatPost;
  replies?: ChatPost[];
  draft?: string;
  onDraftChange?: (text: string) => void;
  onReply?: (text: string) => void | Promise<void>;
}) {
  const [local, setLocal] = useState([studioReply]);
  const items = replies ?? local;
  const list = useRef<HTMLDivElement>(null);
  const previousCount = useRef(items.length);
  useLayoutEffect(() => {
    if (items.length > previousCount.current && list.current)
      list.current.scrollTop = list.current.scrollHeight;
    previousCount.current = items.length;
  }, [items.length]);
  return (
    <section
      aria-label="Обсуждение"
      className={cn(
        "flex h-full min-h-0 w-full flex-col overflow-hidden rounded-xl border bg-card text-card-foreground",
        className,
      )}
    >
      <div className="flex items-center gap-2 border-b px-4 py-3 text-sm font-semibold">
        <MessagesSquare size={16} />
        Обсуждение
      </div>
      <div
        ref={list}
        tabIndex={0}
        className="min-h-0 flex-1 space-y-4 overflow-y-auto overscroll-contain p-4"
      >
        <ChatPostBody post={parent} />
        <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
          <CornerDownRight size={14} />
          Ответы <span className="tabular-nums">{items.length}</span>
        </div>
        {items.map((reply) => (
          <ChatPostBody post={reply} key={reply.id} />
        ))}
      </div>
      <div className="p-2 pt-0">
        <ChatComposer
          pending={pending}
          value={draft}
          onChange={onDraftChange}
          placeholder="Ответить в треде"
          onSend={async (text) => {
            if (onReply) await onReply(text);
            if (replies === undefined)
              setLocal((previous) => [...previous, ownPost(text)]);
          }}
        />
      </div>
    </section>
  );
}

"use client";

