      </Avatar>
      <div className="min-w-0 flex-1">
        <header className="flex flex-wrap items-baseline gap-x-2">
          <strong className="text-sm font-semibold">{post.author}</strong>
          <span className="text-[10px] tabular-nums text-muted-foreground">
