        {children}
      </div>
    </motion.article>
  );
}

.thumbnail {
  position: relative;
  display: grid;
  place-items: center;
  flex: none;
  width: 4rem;
  height: 3rem;
  overflow: hidden;
  border-radius: 0.5rem;
  background: #171717;
  color: #d1fae5;
}

.thumbnail::before,
.thumbnail::after {
  content: "";
  position: absolute;
  width: 6rem;
  height: 3.5rem;
  border: 1px solid rgb(209 250 229 / 25%);
  border-radius: 50%;
  transform: rotate(-28deg);
}

.thumbnail::after {
  width: 5.5rem;
  height: 2rem;
  border-color: rgb(209 250 229 / 30%);
}

@media (prefers-reduced-motion: no-preference) {
  .thumbnail::after {
    transition: transform 150ms;
  }

  a:hover .thumbnail::after {
    transform: rotate(0);
  }
}
